# ============================================================
# SECURITY
# ============================================================
def secure_equal(a, b):
    return hmac.compare_digest(str(a), str(b))


def derive_fallback_secret():
    base = APP_MASTER_SECRET or f"{ADMIN_PASSWORD}|{SCANNER_PASSWORD}|airnexus-secure-app"
    return hashlib.sha256(base.encode("utf-8")).digest()


def get_fernet():
    if APP_ENCRYPTION_KEY:
        try:
            return Fernet(APP_ENCRYPTION_KEY.encode("utf-8"))
        except Exception:
            st.error("APP_ENCRYPTION_KEY in Streamlit Secrets is invalid.")
            st.stop()

    key = base64.urlsafe_b64encode(derive_fallback_secret())
    return Fernet(key)


FERNET = get_fernet()


def get_live_secret_bytes():
    if LIVE_SECURITY_SECRET:
        return LIVE_SECURITY_SECRET.encode("utf-8")
    return hashlib.sha256(derive_fallback_secret() + b":live-code").digest()


LIVE_SECRET = get_live_secret_bytes()


# ============================================================
# QR TOKEN SECURITY
# ============================================================
def new_qr_token():
    return secrets.token_urlsafe(32)


def hash_token(token):
    return hashlib.sha256(token.encode("utf-8")).hexdigest()


def encrypt_token(token):
    return FERNET.encrypt(token.encode("utf-8")).decode("utf-8")


def decrypt_token(enc):
    if not enc:
        return None

    try:
        return FERNET.decrypt(enc.encode("utf-8")).decode("utf-8")
    except (InvalidToken, ValueError, TypeError):
        return None


def build_verification_url(token):
    if APP_BASE_URL:
        return f"{APP_BASE_URL}/?verify={token}"
    return f"http://localhost:8501/?verify={token}"


def make_qr_from_token(token):
    url = build_verification_url(token)

    qr = qrcode.QRCode(
        version=None,
        error_correction=qrcode.constants.ERROR_CORRECT_H,
        box_size=10,
        border=4,
    )

    qr.add_data(url)
    qr.make(fit=True)

    image = qr.make_image(
        fill_color="black",
        back_color="white"
    ).convert("RGB")

    return image, url


def png_bytes(img):
    buff = io.BytesIO()
    img.save(buff, format="PNG")
    return buff.getvalue()


# ============================================================
# PHOTO HELPERS
# ============================================================
def encode_photo(photo_bytes):
    if not photo_bytes:
        return None

    return base64.b64encode(photo_bytes).decode("utf-8")


def decode_photo(photo_text):
    if not photo_text:
        return None

    try:
        return base64.b64decode(photo_text)
    except Exception:
        return None


def photo_image(photo_text):
    photo_bytes = decode_photo(photo_text)

    if not photo_bytes:
        return None

    try:
        return Image.open(io.BytesIO(photo_bytes)).convert("RGB")
    except Exception:
        return None


# ============================================================
# SUPABASE DATABASE FUNCTIONS
# ============================================================
def add_audit(action, member_id=None, card_id=None, details=""):
    supabase.table("admin_audit").insert({
        "action": action,
        "member_id": member_id,
        "card_id": card_id,
        "action_time": datetime.now().isoformat(timespec="seconds"),
        "details": details,
    }).execute()


def add_member(data):
    supabase.table("members").insert(data).execute()

    add_audit(
        "CREATE_MEMBER",
        data["id"],
        data["card_id"],
        "New identity created",
    )


def update_member(member_id, data):
    update_data = dict(data)
    update_data["updated_at"] = datetime.now().isoformat(timespec="seconds")

    supabase.table("members").update(update_data).eq("id", member_id).execute()

    add_audit(
        "UPDATE_MEMBER",
        member_id,
        data["card_id"],
        "Identity record updated",
    )


def delete_member(member_id, card_id):
    supabase.table("members").delete().eq("id", member_id).execute()

    add_audit(
        "DELETE_MEMBER",
        member_id,
        card_id,
        "Identity deleted",
    )


def get_all_members():
    response = (
        supabase
        .table("members")
        .select("*")
        .order("full_name")
        .execute()
    )

    if not response.data:
        return pd.DataFrame(columns=[
            "id", "card_id", "full_name", "category", "position",
            "department", "organization", "email", "phone",
            "emergency_contact", "blood_group", "status", "notes",
            "created_at", "photo", "qr_token_hash", "qr_token_enc",
            "expiry_date", "issue_version", "last_reissued_at", "updated_at"
        ])

    return pd.DataFrame(response.data)


def get_member_by_id(member_id):
    response = (
        supabase
        .table("members")
        .select("*")
        .eq("id", member_id)
        .limit(1)
        .execute()
    )

    if response.data:
        return response.data[0]

    return None


def get_member_by_token(token):
    token_digest = hash_token(token)

    response = (
        supabase
        .table("members")
        .select("*")
        .eq("qr_token_hash", token_digest)
        .limit(1)
        .execute()
    )

    if response.data:
        return response.data[0]

    return None


def reissue_qr(member_id, card_id):
    member = get_member_by_id(member_id)

    if not member:
        return None

    token = new_qr_token()
    next_version = int(member.get("issue_version") or 1) + 1
    now = datetime.now().isoformat(timespec="seconds")

    supabase.table("members").update({
        "qr_token_hash": hash_token(token),
        "qr_token_enc": encrypt_token(token),
        "issue_version": next_version,
        "last_reissued_at": now,
        "updated_at": now,
    }).eq("id", member_id).execute()

    add_audit(
        "REISSUE_QR",
        member_id,
        card_id,
        f"QR rotated to version {next_version}",
    )

    return token


def set_status(member_id, card_id, status):
    supabase.table("members").update({
        "status": status,
        "updated_at": datetime.now().isoformat(timespec="seconds"),
    }).eq("id", member_id).execute()

    add_audit(
        "STATUS_CHANGE",
        member_id,
        card_id,
        f"Status changed to {status}",
    )


def log_scan(member, verification_id, result):
    supabase.table("scan_logs").insert({
        "member_id": member["id"] if member else None,
        "card_id": member["card_id"] if member else None,
        "scan_time": datetime.now().isoformat(timespec="seconds"),
        "verification_id": verification_id,
        "result": result,
    }).execute()


def get_recent_scans(limit=500):
    response = (
        supabase
        .table("scan_logs")
        .select("*")
        .order("id", desc=True)
        .limit(limit)
        .execute()
    )

    if not response.data:
        return pd.DataFrame(
            columns=["scan_time", "card_id", "verification_id", "result"]
        )

    df = pd.DataFrame(response.data)

    wanted = [
        col for col in
        ["scan_time", "card_id", "verification_id", "result"]
        if col in df.columns
    ]

    return df[wanted]


def get_audit_log(limit=500):
    response = (
        supabase
        .table("admin_audit")
        .select("*")
        .order("id", desc=True)
        .limit(limit)
        .execute()
    )

    if not response.data:
        return pd.DataFrame(
            columns=["action_time", "action", "card_id", "details"]
        )

    df = pd.DataFrame(response.data)

    wanted = [
        col for col in
        ["action_time", "action", "card_id", "details"]
        if col in df.columns
    ]

    return df[wanted]


