# ============================================================
# TAB 1 - ISSUE IDENTITY
# ============================================================
with tabs[0]:
    st.subheader("Issue New Secure Identity")

    with st.form(
        "new_member_form",
        clear_on_submit=True
    ):
        c1, c2 = st.columns(2)

        with c1:
            full_name = st.text_input("Full Name *")

            category = st.selectbox(
                "Category *",
                [
                    "Organizer",
                    "Executive Council",
                    "Volunteer",
                    "Guest / Other"
                ]
            )

            position = st.text_input("Position / Designation *")
            department = st.text_input("Committee / Department")
            organization = st.text_input(
                "Organization",
                value="Air University"
            )
            expiry_date = st.date_input(
                "Valid Until",
                value=date.today()
            )

        with c2:
            email = st.text_input("Email")
            phone = st.text_input("Phone")
            emergency_contact = st.text_input("Emergency Contact")

            blood_group = st.selectbox(
                "Blood Group",
                [
                    "",
                    "A+",
                    "A-",
                    "B+",
                    "B-",
                    "AB+",
                    "AB-",
                    "O+",
                    "O-"
                ]
            )

            manual_card_id = st.text_input(
                "Custom Card ID (optional)"
            )

            photo_file = st.file_uploader(
                "Official Photo *",
                type=["jpg", "jpeg", "png"]
            )

            notes = st.text_area("Public Event Note")

        submitted = st.form_submit_button(
            "Issue Secure Identity",
            use_container_width=True
        )

    if submitted:
        if not full_name.strip() or not position.strip():
            st.error("Full Name and Position are required.")

        elif photo_file is None:
            st.error("Official photo is required.")

        else:
            member_id = str(uuid.uuid4())

            card_id = (
                manual_card_id.strip()
                or generate_card_id(category)
            )

            token = new_qr_token()
            now = datetime.now().isoformat(timespec="seconds")

            data = {
                "id": member_id,
                "card_id": card_id,
                "full_name": full_name.strip(),
                "category": category,
                "position": position.strip(),
                "department": department.strip(),
                "organization": organization.strip(),
                "email": email.strip(),
                "phone": phone.strip(),
                "emergency_contact": emergency_contact.strip(),
                "blood_group": blood_group,
                "status": "Active",
                "notes": notes.strip(),
                "created_at": now,
                "photo": encode_photo(photo_file.getvalue()),
                "qr_token_hash": hash_token(token),
                "qr_token_enc": encrypt_token(token),
                "expiry_date": expiry_date.isoformat(),
                "issue_version": 1,
                "last_reissued_at": now,
                "updated_at": now,
            }

            try:
                add_member(data)

                st.success(
                    f"Identity created. Card ID: {card_id}"
                )

                qr_img, verify_url = make_qr_from_token(token)
                card_img = make_id_card(data, token)

                c1, c2 = st.columns([1, 2])

                with c1:
                    st.image(qr_img, width=280)
                    st.code(verify_url)

                    st.download_button(
                        "Download QR",
                        data=png_bytes(qr_img),
                        file_name=f"{card_id}_QR.png",
                        mime="image/png",
                    )

                with c2:
                    st.image(
                        card_img,
                        use_container_width=True
                    )

                    st.download_button(
                        "Download ID Card",
                        data=png_bytes(card_img),
                        file_name=f"{card_id}_Card.png",
                        mime="image/png",
                    )

            except Exception as exc:
                st.error(f"Could not create identity: {exc}")


