# TAB 2 - MANAGE
# ============================================================
with tabs[1]:
    st.subheader("Manage Identities")

    if members_df.empty:
        st.info("No identities available.")

    else:
        selected_label = st.selectbox(
            "Select Identity",
            [
                f"{r.full_name} — {r.card_id}"
                for r in members_df.itertuples()
            ],
            index=None
        )

        if selected_label:
            selected_card_id = selected_label.rsplit(" — ", 1)[-1]

            member_id = members_df.loc[
                members_df["card_id"] == selected_card_id,
                "id"
            ].iloc[0]

            member = get_member_by_id(member_id)
            pimg = photo_image(member.get("photo"))

            if pimg:
                st.image(pimg, width=200)

            st.write(f"**Name:** {member['full_name']}")
            st.write(f"**Position:** {member['position']}")
            st.write(f"**Status:** {member['status']}")

            c1, c2, c3 = st.columns(3)

            with c1:
                if st.button("Revoke Card", use_container_width=True):
                    set_status(
                        member["id"],
                        member["card_id"],
                        "Revoked"
                    )

                    st.success("Card revoked.")
                    st.rerun()

            with c2:
                if st.button("Reissue QR", use_container_width=True):
                    new_token = reissue_qr(
                        member["id"],
                        member["card_id"]
                    )

                    st.success(
                        "New QR issued. Old QR is invalid."
                    )

                    qr_img, _ = make_qr_from_token(new_token)
                    st.image(qr_img, width=220)

                    st.download_button(
                        "Download Reissued QR",
                        data=png_bytes(qr_img),
                        file_name=f"{member['card_id']}_REISSUED_QR.png",
                        mime="image/png",
                    )

            with c3:
                if st.button(
                    "Delete Record",
                    type="primary",
                    use_container_width=True
                ):
                    delete_member(
                        member["id"],
                        member["card_id"]
                    )

                    st.success("Record deleted.")
                    st.rerun()


